<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetSnippetVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;

trait SnippetAssetSnippetAccessor
{
    private SnippetAssetSnippetVO $_snippet;
    public function getSnippet(): SnippetRef
    {
        return $this->_snippet->value();
    }
    public function snippet(): SnippetAssetSnippetVO
    {
        return $this->_snippet;
    }
    public function isSnippetChanged(?self $original = null): bool
    {
        return !$this->_snippet->equals($original?->_snippet);
    }
    public function withSnippet(SnippetAssetSnippetVO|SnippetRef $snippet): self
    {
        $copy = clone $this;
        $copy->_snippet = SnippetAssetSnippetVO::from($snippet);
        return $copy;
    }
}
